EXTRACTOR = "manual_statutory_codification:v1"

conn = psycopg.connect(DB)
cur = conn.cursor()


def ensure_clause(sv_id, key, title, section_ref, text):
    cur.execute(
        """INSERT INTO clauses
           (id, source_version_id, clause_key, clause_type, title, section_ref,
            disposition, text, quote, parser_name, parser_version,
            metadata_json, created_at, updated_at)
           VALUES (%s, %s, %s, 'section', %s, %s, 'rule_bearing', %s, %s,
                   'manual_statutory_codification', 'v1', '{}', now(), now())
           ON CONFLICT ON CONSTRAINT uq_clauses_version_key DO NOTHING""",
        (str(uuid.uuid4()), sv_id, key, title, section_ref, text, text),
    )
    cur.execute(
        "SELECT id FROM clauses WHERE source_version_id = %s AND clause_key = %s",
        (sv_id, key),
    )
    return str(cur.fetchone()[0])


def cand(sv_id, clause_ids, clause_key, rule_key, quote, section, ref,
         operator=None, value=None, unit=None, condition=None,
         check_type="boolean_presence", evaluable="yes",
         rule_type="requirement", canonical=None):
    vj = {"value": value} if value is not None else {"base_rule_key": canonical or rule_key}
    return {
        "rule_key": rule_key,
        "canonical_rule_key": canonical or rule_key,
        "rule_type": rule_type,
        "pathway": "none",
        "dwelling_type": None,
        "applicable_r_codes": None,
        "applicable_zones": None,
        "council_scope": None,
        "operator": operator,
        "value_json": vj,
        "unit": unit,
        "condition_json": condition or {},
        "quote": quote,
        "instrument_section": section,
        "table_reference": ref,
        "effective_from": None,
        "effective_to": None,
        "source_version_id": sv_id,
        "clause_id": clause_ids[clause_key],
        "extractor_model": EXTRACTOR,
        "check_type": check_type,
        "evaluable": evaluable,
    }


